CREATE TYPE "DealSourceType" AS ENUM ('RSS', 'MANUAL');
CREATE TYPE "DealStatus" AS ENUM ('NEW', 'VERIFIED', 'EXPIRED');
CREATE TYPE "MileagePromoStatus" AS ENUM ('ACTIVE', 'INACTIVE', 'EXPIRED');
ALTER TABLE "NotificationLog" ALTER COLUMN "alertId" DROP NOT NULL;
ALTER TABLE "NotificationLog" ADD COLUMN "userId" TEXT, ADD COLUMN "type" TEXT NOT NULL DEFAULT 'PRICE_ALERT';
CREATE TABLE "DealSource" ("id" TEXT PRIMARY KEY, "name" TEXT NOT NULL, "type" "DealSourceType" NOT NULL, "url" TEXT, "enabled" BOOLEAN NOT NULL DEFAULT true, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "Deal" ("id" TEXT PRIMARY KEY, "sourceId" TEXT NOT NULL, "title" TEXT NOT NULL, "origin" TEXT, "destination" TEXT, "price" DOUBLE PRECISION, "currency" TEXT DEFAULT 'BRL', "originalUrl" TEXT NOT NULL, "publishedAt" TIMESTAMP(3) NOT NULL, "status" "DealStatus" NOT NULL DEFAULT 'NEW', "discountScore" DOUBLE PRECISION, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Deal_sourceId_fkey" FOREIGN KEY ("sourceId") REFERENCES "DealSource"("id") ON DELETE CASCADE);
CREATE UNIQUE INDEX "Deal_sourceId_originalUrl_key" ON "Deal"("sourceId","originalUrl"); CREATE INDEX "Deal_status_publishedAt_idx" ON "Deal"("status","publishedAt"); CREATE INDEX "Deal_origin_destination_idx" ON "Deal"("origin","destination");
CREATE TABLE "MileageTransferPromo" ("id" TEXT PRIMARY KEY, "sourceProgram" TEXT NOT NULL, "destinationProgram" TEXT NOT NULL, "bonusPercent" INTEGER NOT NULL, "validFrom" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "validUntil" TIMESTAMP(3) NOT NULL, "officialUrl" TEXT NOT NULL, "createdById" TEXT NOT NULL, "status" "MileagePromoStatus" NOT NULL DEFAULT 'ACTIVE', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "MileageTransferPromo_createdById_fkey" FOREIGN KEY ("createdById") REFERENCES "User"("id") ON DELETE RESTRICT);
CREATE INDEX "MileageTransferPromo_destinationProgram_status_validUntil_idx" ON "MileageTransferPromo"("destinationProgram","status","validUntil");
CREATE TABLE "MileagePromoSubscription" ("id" TEXT PRIMARY KEY, "userId" TEXT NOT NULL UNIQUE, "active" BOOLEAN NOT NULL DEFAULT true, "lastNotifiedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "MileagePromoSubscription_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE);
ALTER TABLE "NotificationLog" ADD CONSTRAINT "NotificationLog_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE;
